;Tailgunner (Cinematronics, 1979) - memory map, I/O and RAM words for
;tailgunner_program_rom.asm.
;The CCPU has separate program and data spaces: 8K of program ROM, fetched as
;bytes, and 256 words of 12-bit data RAM, addressed as 16 pages of 16 words
;(the P register picks the page, the opcode the word). I/O is not memory
;mapped: INP reads one bit, OUT writes one bit, JMI tests the joystick.
;Hardware notes are from the AAE Cinematronics driver (after MAME's cinemat.cpp).
;RAM names are this disassembly's; unnamed words are RAM_xx. [rN wM] counts the
;instructions that read / wrote the word in the traces (instructions, not
;accesses; the power-on RAM clear at L000B is one of the writers of every word).
;Generated by disasm/emit_defines.py.

;----------------------------------[ Memory map ]----------------------------------
.alias Bank0Rom           $0000    ;Through $0FFF. tgunner.t70 (even bytes) + tgunner.p70 (odd bytes).
.alias Bank1Rom           $1000    ;Through $1FFF. tgunner.t71 (even bytes) + tgunner.p71 (odd bytes).
.alias DataRam            $00      ;Through $FF: 256 words x 12 bits, page = P register, word = opcode low nibble.

;----------------------------------[ Inputs (INP n with the A accumulator, active low) ]----------------------------------
.alias IN_FIRE            $5       ;fire button (active low)
.alias IN_SHIELD          $6       ;shield button (active low)
.alias IN_START           $7       ;start button (active low)

;----------------------------------[ Switches (INP n with the B accumulator) ]----------------------------------
.alias SW_COINAGE         $0       ;DIP bit 2: coinage, 1 = 1 coin 1 credit, 0 = 2 coins 1 credit
.alias SW_SHIELD_HI       $1       ;DIP bit 5: shield points, high bit (with SW_SHIELD_LO0/LO1)
.alias SW_UNK_4           $2       ;DIP bit 4: unknown in MAME
.alias SW_UNK_3           $3       ;DIP bit 3: unknown in MAME
.alias SW_SHIELD_LO0      $4       ;DIP bit 0: shield points, low bit 0
.alias SW_SHIELD_LO1      $5       ;DIP bit 1: shield points, low bit 1
.alias SW_UNK_6           $6       ;DIP bit 6: unknown in MAME
.alias SW_COIN            $7       ;coin latch: 0 once a coin has dropped, until OUT 5 resets it

;----------------------------------[ Outputs (OUT n writes the inverse of A bit 0) ]----------------------------------
.alias OUT_SND_A0         $0       ;sound latch address bit 0
.alias OUT_SND_A1         $1       ;sound latch address bit 1
.alias OUT_SND_A2         $2       ;sound latch address bit 2
.alias OUT_SND_DATA       $3       ;sound latch data bit
.alias OUT_SND_STROBE     $4       ;sound strobe: the falling edge writes DATA into sound bit A2-A0
.alias OUT_COIN_RESET     $5       ;coin latch reset: the rising edge of the latch input (A bit 0 going 1 -> 0) clears it
.alias OUT_INTENSITY      $6       ;vector intensity: A bit 0 = 1 bright, 0 dim
.alias OUT_MUX            $7       ;joystick multiplexer: A bit 0 = 0 selects the x axis for JMI, 1 the y axis
;JMI and JMIB jump when the stick axis that OUT_MUX selects is past the X register;
;the game finds the stick position by successive tests.

;----------------------------------[ Sound board register (written one bit at a time through OUT 0-4; 0 = on) ]----------------------------------
.alias SND_EXPLOSION      $0       ;sound register bit 0: explosion
.alias SND_RUMBLE         $1       ;sound register bit 1: rumble
.alias SND_LASER          $2       ;sound register bit 2: laser
.alias SND_SHIELD         $3       ;sound register bit 3: shield
.alias SND_BOUNCE         $4       ;sound register bit 4: bounce
.alias SND_HYPERSPACE     $5       ;sound register bit 5: hyperspace

;----------------------------------[ Data RAM ]----------------------------------
.alias RET0               $00      ;return address for FTRUPDATE, PRINT and DRAWFTRS (also the RAM-clear pointer at RESET)  [r8 w18; in RESET, FIGHTER1, FIGHTER2, FIGHTER3, TOBANK1 ...]
.alias TMP01              $01      ;PRINT: $FF, the end-of-string marker; lasers: address of the last beam step (BEAMDONE)  [r3 w3; in BOLT, BOLTSTEP3, PRINT, PRINTCHR]
