;Vertex buffer $E0-$FF: not drawn itself. DRAWMODEL3D projects a model's
;vertices one at a time and keeps each one's screen position here (x + $200,
;y + $180, at L1395 / L139B); DRAWEDGES reads two of them for every edge byte,
;skips the edge when an end is off screen (x >= $400 or y >= $300), else moves
;the beam to the first (IV) and draws to the second (DV). A vertex is projected
;only when an edge first needs it (L13AF), so projecting and drawing alternate.
;Every model drawn overwrites it; 4-bit vertex numbers allow 16 vertices.
.alias VTX0_X             $E0      ;vertex buffer: screen x of vertex 0 of the model being drawn  [r2 w2]
.alias VTX0_Y             $E1      ;vertex buffer: screen y of vertex 0  [r2 w2]
.alias VTX1_X             $E2      ;vertex buffer: screen x of vertex 1 of the model being drawn  [r2 w2]
.alias VTX1_Y             $E3      ;vertex buffer: screen y of vertex 1  [r2 w2]
.alias VTX2_X             $E4      ;vertex buffer: screen x of vertex 2 of the model being drawn  [r2 w2]
.alias VTX2_Y             $E5      ;vertex buffer: screen y of vertex 2  [r2 w2]
.alias VTX3_X             $E6      ;vertex buffer: screen x of vertex 3 of the model being drawn  [r2 w2]
.alias VTX3_Y             $E7      ;vertex buffer: screen y of vertex 3  [r2 w2]
.alias VTX4_X             $E8      ;vertex buffer: screen x of vertex 4 of the model being drawn  [r2 w2]
.alias VTX4_Y             $E9      ;vertex buffer: screen y of vertex 4  [r2 w2]
